public static Boolean deleteObjectFromAzure(String path) {
    Boolean isFileDeleted = Boolean.FALSE
    if (path) {
        String containerReference = path.split("/")[0]
        String blobReference = path.replaceAll("${containerReference}/", "")
        final String storageConnectionString = Holders.getFlatConfig().get("azure.storageConnectionString")
        try {
            CloudStorageAccount storageAccount = CloudStorageAccount.parse(storageConnectionString)
            CloudBlobClient blobClient = storageAccount.createCloudBlobClient()
            CloudBlobContainer container = blobClient.getContainerReference(containerReference)
            CloudBlockBlob blob = container.getBlockBlobReference(blobReference)
            blob.deleteIfExists()
//            if (!container.listBlobs())
//                container.deleteIfExists()
            isFileDeleted = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while deleting file to Azure ==>> ${e.message}", e)
        }
    }
    isFileDeleted
}

// ********************** GOOGLE CLOUD STORAGE **********************

public static Boolean uploadObjectToGoogleCloudStorage(File file, String path) {
    Boolean isFileUploaded = Boolean.FALSE
    if (path) {
        try {
            String bucketName = Holders.getFlatConfig().get("google.cloud.storage.bucket.name")
            Storage storage = StorageOptions.getDefaultInstance().getService()
            BlobId blobId = BlobId.of(bucketName, path)
            BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build()
            storage.create(blobInfo, file.bytes)
            isFileUploaded = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileUploaded
}

public static InputStream downloadObjectFromGoogleCloudStorage(String path) {
    InputStream inputStream = null
    if (path) {
        try {
            String bucketName = Holders.getFlatConfig().get("google.cloud.storage.bucket.name")
            Storage storage = StorageOptions.getDefaultInstance().getService()
            Blob blob = storage.get(BlobId.of(bucketName, path))
            if (blob != null) {
                inputStream = new ByteArrayInputStream(blob.getContent())
            }
        }
        catch (Exception e) {
            log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    inputStream
}

public static Boolean deleteObjectFromGoogleCloudStorage(String path) {
    Boolean isFileDeleted = Boolean.FALSE
    if (path) {
        try {
            String bucketName = Holders.getFlatConfig().get("google.cloud.storage.bucket.name")
            Storage storage = StorageOptions.getDefaultInstance().getService()
            storage.delete(bucketName, path)
            isFileDeleted = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while deleting file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileDeleted
}

public static void uploadObjectToLocalOrGoogle(File pdfFile, String documentPath = null) {
    if (GrailsUtil.developmentEnv) {
        log.info("=== Requesting file to be uploaded on Local location ===>>> ${documentPath}")
        File file = new File(documentPath)
        FileUtils.writeByteArrayToFile(file, pdfFile.getBytes())
    } else {
        log.info("=== Requesting file to be uploaded on Google Cloud Storage location ===>>> ${documentPath}")
        uploadObjectToGoogleCloudStorage(pdfFile, documentPath)
    }
}

